package main

import (
	"math"

	"github.com/tdr16/canvas/sdflcanvas"
)

func main() {
	wnd, cv, err := sdflcanvas.CreateWindow(1280, 720, "Hello")
	if err != nil {
		panic(err)
	}
	defer wnd.Destroy()

	wnd.MainLoop(func() {
		w, h := Float64(cv.Width()), Float64(cv.Height())
		cv.SetFillStyle(int(10), int(20), int(100), int(100))
		cv.FillRect(0, 0, w, h)

		for r := 0.0; r < math.Pi*2; r = r + math.Pi*0.1 {
			cv.NewPath()
			cv.MoveTo(w*0.5, h*0.5)
			cv.Arc(w*0.5, h*0.5, math.Min(w, h)*0.4, r, r+0.1*math.Pi, false)
			cv.ClosePath()
			cv.Fill()
		}

		cv.SetStrokeStyle(10)
		cv.BggiLineWidth(10)
		cv.Arc(w*0.5, h*0.5, math.Min(w, h)*0.4, 0, math.Pi*2, false)
		cv.Stroke()
	})
}
